import ast, sys
with open('poc.py') as f:
    tree = ast.parse(f.read())
stdlib_imports = {'json', 'os', 'struct', 'subprocess', 'sys', 'tempfile', 'time', 'argparse', 'signal'}
for node in ast.walk(tree):
    if isinstance(node, ast.Import):
        for alias in node.names:
            top = alias.name.split('.')[0]
            if top not in stdlib_imports:
                print(f'Non-stdlib import: {alias.name}')
                sys.exit(1)
    elif isinstance(node, ast.ImportFrom):
        if node.module and node.module.split('.')[0] not in stdlib_imports:
            print(f'Non-stdlib import from: {node.module}')
            sys.exit(1)
print('All imports are stdlib')
"

